import React from 'react';

interface IconProps extends React.HTMLAttributes<HTMLSpanElement> {
  className?: string;
  size?: number;
}

const HOME_DATA = 'data:image/png;base64,';
const MESSAGES_DATA = 'data:image/png;base64,';
const TEAMS_DATA = 'data:image/png;base64,';
const BELL_DATA = 'data:image/png;base64,';
const SWORDS_DATA = 'data:image/png;base64,';

function MaskIcon({
  src,
  className = 'w-5 h-5',
  size,
  style,
  ...props
}: IconProps & { src: string }) {
  const sizeStyle: React.CSSProperties = size ? { width: size, height: size } : {};

  return (
    <span
      className={`inline-block shrink-0 bg-current ${className}`}
      style={{
        ...sizeStyle,
        maskImage: 'url(' + src + ')',
        WebkitMaskImage: 'url(' + src + ')',
        maskSize: 'contain',
        WebkitMaskSize: 'contain',
        maskRepeat: 'no-repeat',
        WebkitMaskRepeat: 'no-repeat',
        maskPosition: 'center',
        WebkitMaskPosition: 'center',
        ...style,
      }}
      aria-hidden="true"
      {...props}
    />
  );
}

/**
 * 1. Home Icon
 */
export function HomeIcon(props: IconProps) {
  return <MaskIcon src={HOME_DATA} {...props} />;
}

/**
 * 2. Messages / Chat Bubble Icon
 */
export function MessagesIcon(props: IconProps) {
  return <MaskIcon src={MESSAGES_DATA} {...props} />;
}

/**
 * 3. Teams / Community Icon
 */
export function TeamsIcon(props: IconProps) {
  return <MaskIcon src={TEAMS_DATA} {...props} />;
}

/**
 * 4. Notifications Bell Icon
 */
export function BellIcon(props: IconProps) {
  return <MaskIcon src={BELL_DATA} {...props} />;
}

/**
 * 5. Crossed Swords / Scrims & Battle Icon
 */
export function SwordsIcon(props: IconProps) {
  return <MaskIcon src={SWORDS_DATA} {...props} />;
}

export { SwordsIcon as ScrimsIcon };

/**
 * 6. Settings Gear Icon (Filled Solid 6-tooth Cog)
 */
export function SettingsIcon({ className = '', ...props }: React.SVGProps<SVGSVGElement>) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="currentColor"
      className={`inline-block shrink-0 ${className}`}
      {...props}
    >
      <path
        fillRule="evenodd"
        clipRule="evenodd"
        d="M12 1a3 3 0 0 0-2.83 2H8.5a3 3 0 0 0-2.6 1.5l-.67 1.15a3 3 0 0 0 .23 3.35l.4.52a3 3 0 0 0 0 3.46l-.4.52a3 3 0 0 0-.23 3.35l.67 1.15a3 3 0 0 0 2.6 1.5h.67a3 3 0 0 0 2.83 2h1.66a3 3 0 0 0 2.83-2h.67a3 3 0 0 0 2.6-1.5l.67-1.15a3 3 0 0 0-.23-3.35l-.4-.52a3 3 0 0 0 0-3.46l.4-.52a3 3 0 0 0 .23-3.35l-.67-1.15a3 3 0 0 0-2.6-1.5h-.67a3 3 0 0 0-2.83-2h-1.66zM12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8z"
      />
    </svg>
  );
}

